const nav=document.getElementById('nav'),menu=document.getElementById('menu'),links=nav.querySelector('nav');window.addEventListener('scroll',()=>nav.classList.toggle('scrolled',scrollY>30),{passive:true});menu.addEventListener('click',()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.textContent=open?'×':'☰'});links.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{links.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'}));document.getElementById('year').textContent=new Date().getFullYear();document.getElementById('lang').addEventListener('click',()=>{window.open('https://semanoor.com/ar/','_blank','noopener')});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('inview')}),{threshold:.25});observer.observe(document.querySelector('.device'));
const steps=[...document.querySelectorAll('.step')];const caption=document.getElementById('stageCaption');const words=document.getElementById('stageWords');const stageLabels=['01 — PRINT','02 — DIGITAL','03 — INTERACTIVE','04 — IMMERSIVE'];const stageWords=['THE FIRST SPARK','A WORLD OPENS','LEARNING COMES ALIVE','KNOWLEDGE INTO ACTION'];const dots=[...document.querySelectorAll('.stage-dots i')];let currentStage=-1;function setJourneyStage(n){if(n===currentStage)return;currentStage=n;steps.forEach((step,i)=>step.classList.toggle('active',i===n));dots.forEach((dot,i)=>dot.classList.toggle('active',i===n));caption.textContent=stageLabels[n];words.textContent=stageWords[n];document.dispatchEvent(new CustomEvent('journey-stage',{detail:n}))}function updateJourney(){const marker=innerHeight*.48;let active=0;steps.forEach((step,i)=>{if(step.getBoundingClientRect().top<=marker)active=i});setJourneyStage(active)}addEventListener('scroll',updateJourney,{passive:true});addEventListener('resize',updateJourney);updateJourney();steps.forEach((step,i)=>step.addEventListener('click',()=>setJourneyStage(i)));

const nationalClose=document.getElementById('nationalClose');nationalClose?.addEventListener('click',()=>{document.body.classList.remove('national-visible');document.getElementById('nationalBanner').hidden=true});
